mapper.select:
SELECT
    f.foodMaterial_Id      AS foodMaterialId,
    f.foodMaterialName     AS foodMaterialName,
    f.totalWeight AS totalWeight
FROM USED u
         JOIN FOODM f ON u.foodMaterial_Id = f.foodMaterial_Id
WHERE u.menu_Id = #{menuId}
  AND f.bId = #{bId}
  AND f.totalWeight <= #{foodmLimit}
GROUP BY f.foodMaterial_Id, f.foodMaterialName, f.totalWeight
